const modelCallOperationHasFailedWithErrorKind = `-- name: ModelCallOperationHasFailedWithErrorKind :one
WITH current_context AS MATERIALIZED (
  SELECT context.project_id, context.agent_id, context.id,
         context.operation_kind, context.input_event_sequence
  FROM model_call_contexts context
  WHERE context.project_id = $2
    AND context.agent_id = $3
    AND context.id = $4
)
SELECT EXISTS (
  SELECT 1
  FROM current_context current
  JOIN model_call_contexts sibling ON sibling.project_id = current.project_id
    AND sibling.agent_id = current.agent_id
    AND sibling.operation_kind = current.operation_kind
    AND sibling.input_event_sequence = current.input_event_sequence
    AND sibling.id <> current.id
  WHERE sibling.state = 'failed'
    AND sibling.error_kind = $1
) AS failed
`

type ModelCallOperationHasFailedWithErrorKindParams struct {
	ErrorKind          string
	ProjectID          uuid.UUID
	AgentID            uuid.UUID
	ModelCallContextID uuid.UUID
}

func (q *Queries) ModelCallOperationHasFailedWithErrorKind(ctx context.Context, arg ModelCallOperationHasFailedWithErrorKindParams) (bool, error) {
	row := q.db.QueryRow(ctx, modelCallOperationHasFailedWithErrorKind,
		arg.ErrorKind,
		arg.ProjectID,
		arg.AgentID,
		arg.ModelCallContextID,
	)
	var failed bool
	err := row.Scan(&failed)
	return failed, err
}

const openingContentInputSetMatchesInputSequence = `-- name: OpeningContentInputSetMatchesInputSequence :one
WITH requested AS (
  SELECT input_id
  FROM unnest($1::uuid[]) AS input_ids(input_id)
),
requested_distinct AS (
  SELECT DISTINCT input_id
  FROM requested
),
target_turn AS MATERIALIZED (
  SELECT agent_turn_id_at_event_sequence(
    $2,
    $3
  ) AS turn_id
),
opening AS (
  SELECT opening.input_id
  FROM target_turn turn
  CROSS JOIN LATERAL agent_model_call_opening_content_inputs(
    $4,
    $2,
    turn.turn_id,
    $3
  ) AS opening(input_id, event_sequence)
)
SELECT (
  (SELECT count(*) FROM requested) = (SELECT count(*) FROM requested_distinct)
  AND NOT EXISTS (
    SELECT input_id FROM requested_distinct
    EXCEPT
    SELECT input_id FROM opening
  )
  AND NOT EXISTS (
    SELECT input_id FROM opening
    EXCEPT
    SELECT input_id FROM requested_distinct
  )
)::boolean
`

type OpeningContentInputSetMatchesInputSequenceParams struct {
	InputIds           []uuid.UUID
	AgentID            uuid.UUID
	InputEventSequence int64
	ProjectID          uuid.UUID
}

func (q *Queries) OpeningContentInputSetMatchesInputSequence(ctx context.Context, arg OpeningContentInputSetMatchesInputSequenceParams) (bool, error) {
	row := q.db.QueryRow(ctx, openingContentInputSetMatchesInputSequence,
		arg.InputIds,
		arg.AgentID,
		arg.InputEventSequence,
		arg.ProjectID,
	)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
